var nickname: String? = nil       // the box is empty
nickname = "Ada"                  // now it holds a value

// Optional binding: open the box, and only run if something was inside
if let nickname {
    print("Hello, \(nickname)")   // nickname is String here, not String?
}

// guard: leave early when the box is empty
func greet(_ nickname: String?) -> String {
    guard let nickname else { return "Hello, stranger" }
    return "Hello, \(nickname)"
}

// Nil-coalescing: a default when the box is empty
let display = nickname ?? "Anonymous"

// Optional chaining: do nothing gracefully if anything along the way is nil
let initial = nickname?.first        // Character?
let shout   = nickname?.uppercased() // String?

// A closure stored in a variable
let double: (Int) -> Int = { n in n * 2 }

// Captured storage is shared, not copied
func makeCounter() -> () -> Int {
    var count = 0                 // lives on past this function returning
    return { count += 1; return count }
}
let next = makeCounter()
next()  // 1
next()  // 2   — the same `count`, still alive

// Trailing closure syntax
let evens = (1...10).filter { $0.isMultiple(of: 2) }

final class Loader {
    var onFinish: (() -> Void)?

    // non-escaping: called before we return, no `self.` needed
    func each(_ items: [Int], _ body: (Int) -> Void) {
        for item in items { body(item) }
    }

    // @escaping: stored for later — `self.` is now mandatory
    func whenDone(_ handler: @escaping () -> Void) {
        onFinish = handler
    }

    func start() {
        whenDone { [weak self] in
            self?.cleanUp()      // weak: the closure no longer keeps Loader alive
        }
    }

    func cleanUp() {}
}

struct PointValue { var x = 0 }
final class PointRef { var x = 0 }

var a = PointValue(); var b = a
b.x = 10
// a.x == 0   — b is an independent copy

let c = PointRef(); let d = c
d.x = 10
// c.x == 10  — same object, and note `let` didn't stop the mutation

// `let` on a struct freezes its contents; on a class it only freezes the pointer
let frozen = PointValue()
// frozen.x = 1        // error: frozen is a let constant
let stillMutable = PointRef()
stillMutable.x = 1     // fine — the reference is constant, the object isn't

protocol ContentLoading {
    func loadConcepts() async throws -> [String]
}

// A struct conforms — no base class, no inheritance
struct BundleLoader: ContentLoading {
    func loadConcepts() async throws -> [String] { ["arc", "actors"] }
}

// So does a test double
struct FailingLoader: ContentLoading {
    func loadConcepts() async throws -> [String] { throw URLError(.notConnectedToInternet) }
}

// Default behaviour for every conformer, in one place
extension ContentLoading {
    func loadCount() async throws -> Int { try await loadConcepts().count }
}

// Retroactive conformance: teach a type you don't own a new trick
extension Int: @retroactive Identifiable {
    public var id: Int { self }
}

// One concrete type, resolved at compile time — no runtime box
func makeLoader() -> some ContentLoading { BundleLoader() }

// Genuinely heterogeneous — needs the existential box
let loaders: [any ContentLoading] = [BundleLoader(), FailingLoader()]

// Generic constraint: the caller picks the type, the body stays static
func count<L: ContentLoading>(using loader: L) async throws -> Int {
    try await loader.loadConcepts().count
}
